private parameterDefinition(command: PowerShellCmdletDefinition, name: string): PowerShellParameterDefinition | undefined {
    for (const set of command.parameterSets) {
      const found = set.parameters.find((parameter) => parameter.name.toLowerCase() === name.toLowerCase());
      if (found) return found;
    }
    return undefined;
  }

